-- NovelAI — Публікації
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'novelai.net' OR LOWER(`name`) = LOWER('NovelAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'NovelAI', NULL, 'https://novelai.net', NULL, NULL, 'AI-помічник для написання історій і генератор аніме-зображень із захистом приватності: шифровані запити та повні комерційні права на результат.', 'An AI storytelling assistant and anime image generator with privacy built in: encrypted prompts and full commercial rights to your output.', 'NovelAI поєднує два творчі інструменти: помічника для написання історій, який продовжує й розвиває ваш текст, і генератор аніме-зображень з інструментами послідовності персонажів, інпейнтингом і редагуванням. Сервіс робить наголос на приватності: запити шифруються, а згенеровані зображення не зберігаються на серверах. Користувачі зберігають повні комерційні права на створене. Працює в браузері, зокрема на мобільних. Підписка — від $10 на місяць, також можна купувати внутрішню валюту Anlas для додаткових генерацій.', 'NovelAI combines two creative tools: a storytelling assistant that continues and develops your text, and an anime image generator with character consistency tools, inpainting and editing. Privacy is a priority: prompts are encrypted and generated images are not stored on servers. Users keep full commercial rights to what they create. It runs in the browser, including on mobile. Subscriptions start at $10 a month, and you can also buy Anlas, an in-app currency, for extra generations.', 'Помічник для написання історій
Генерація аніме-зображень
Послідовність персонажів та інпейнтинг
Шифровані запити', 'Storytelling assistant
Anime image generation
Character consistency and inpainting
Encrypted prompts', 'Письменники-аматори, автори фанфіків і художники.', 'Hobby writers, fan fiction authors and artists.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'novelai.net' OR LOWER(`name`) = LOWER('NovelAI')) ORDER BY `id` LIMIT 1);
