-- Novelcrafter — Публікації
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'novelcrafter.com' OR LOWER(`name`) = LOWER('Novelcrafter'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Novelcrafter', NULL, 'https://www.novelcrafter.com', NULL, NULL, 'Платформа для написання романів: планування, Codex для персонажів і світу, серії книг та AI-функції з вашими власними ключами моделей.', 'A novel-writing platform: planning, a Codex for characters and worldbuilding, book series and AI features using your own model keys.', 'Novelcrafter допомагає письменникам від задуму до готового рукопису. Codex зберігає персонажів, місця й правила світу, книги можна об''єднувати в серії, а AI-функції — підсумки сцен, витягування персонажів, чат-майстерня й рецензування — працюють з вашими власними API-ключами до моделей. Тарифи: Scribe — $4 на місяць (інструменти письма, необмежені книги); Hobbyist — $8 (AI з власними ключами); Artisan — $14 (чат-майстерня й рецензування); Specialist — $20 (спільне письмо й команда). Є 21 день безкоштовно, ціни без акцій; після скасування дані доступні для читання.', 'Novelcrafter helps writers go from idea to finished manuscript. The Codex stores characters, places and world rules, books can be grouped into series, and AI features — scene summaries, character extraction, workshop chat and review — work with your own API keys for models. Plans: Scribe — $4 a month (writing tools, unlimited books); Hobbyist — $8 (AI with your own keys); Artisan — $14 (workshop chat and review); Specialist — $20 (collaborative writing and teams). There is a 21-day free trial and no sales or discounts; after cancelling, your data stays readable.', 'Codex для персонажів і світу
Серії книг і необмежені книги
AI з власними ключами моделей
Спільне письмо (Specialist)', 'Codex for characters and worldbuilding
Book series and unlimited books
AI with your own model keys
Collaborative writing (Specialist)', 'Письменники художньої літератури.', 'Fiction writers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
