-- Squibler — Публікації
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'squibler.io' OR LOWER(`name`) = LOWER('Squibler'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Squibler', NULL, 'https://www.squibler.io', NULL, NULL, 'AI-помічник для книжок і сценаріїв: генерує повноформатні рукописи на 200–300 сторінок, зберігає узгодженість сюжету й експортує в PDF і DOCX.', 'An AI assistant for books and screenplays: it generates full-length 200–300-page manuscripts, keeps the plot consistent and exports to PDF and DOCX.', 'Squibler допомагає письменникам розробляти романи й сценарії зі збереженням узгодженості сюжету — наприклад, продумати сюжетні повороти чи хибні сліди в детективі. Платні тарифи генерують повноформатні рукописи на 200–300 сторінок і експортують їх у PDF та DOCX. Сервісом користуються понад 20 000 авторів, права на текст залишаються за ними. Тарифи: Free — 1 000 AI-кредитів на місяць; Plus — $15,83 на місяць при річній оплаті ($29,99 помісячно, 10 000 кредитів); Pro — $49,17 на місяць при річній оплаті ($89,99 помісячно, необмежені кредити).', 'Squibler helps writers develop novels and screenplays while keeping the plot consistent — for example, working out plot twists or red herrings in a mystery. Paid plans generate full-length 200–300-page manuscripts and export them to PDF and DOCX. More than 20,000 authors use it, and they keep ownership of their work. Plans: Free — 1,000 AI credits a month; Plus — $15.83 a month billed annually ($29.99 monthly, 10,000 credits); Pro — $49.17 a month billed annually ($89.99 monthly, unlimited credits).', 'Генерація повноформатних рукописів
Книги й сценарії
Узгодженість сюжету
Експорт у PDF і DOCX', 'Full-length manuscript generation
Books and screenplays
Plot consistency
Export to PDF and DOCX', 'Письменники, сценаристи й автори нон-фікшн.', 'Novelists, screenwriters and non-fiction authors.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
