SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ramp.com' OR LOWER(`name`) = LOWER('Ramp'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ramp', NULL, 'https://ramp.com', NULL, NULL, 'Фінансова платформа для бізнесу з AI: корпоративні картки, контроль витрат і відряджень, рахунки до сплати й автоматизація бухгалтерії з AI-перевіркою витрат.', 'An AI-powered finance platform for businesses: corporate cards, expense and travel management, accounts payable and accounting automation with AI expense review.', 'Ramp об''єднує корпоративні картки, облік витрат і відряджень, оплату рахунків, виставлення рахунків, казначейство та автоматизацію бухгалтерії з інтеграціями QuickBooks і Xero. Тариф Plus додає AI-перевірку витрат, розширену роботу з рахунками, інтеграції з NetSuite і Sage Intacct, кілька юросіб і глобальне покриття. Сервісом користуються понад 70 000 фінансових команд. Тарифи: Free — $0 за користувача; Plus — $15 за користувача на місяць плюс платформний збір (знижка 20% при річній оплаті, 30 днів безкоштовно); Enterprise — індивідуально. Сервіс орієнтований на компанії в США.', 'Ramp combines corporate cards, expense and travel management, bill payments, invoicing, treasury and accounting automation with QuickBooks and Xero integrations. The Plus plan adds AI expense review, advanced accounts payable, NetSuite and Sage Intacct integrations, multi-entity support and global coverage. More than 70,000 finance teams use it. Plans: Free — $0 per user; Plus — $15 per user a month plus a platform fee (20% off annual billing, 30-day free trial); Enterprise — custom. The service is aimed at US companies.', 'Корпоративні картки й облік витрат
AI-перевірка витрат (Plus)
Оплата рахунків і бухгалтерія
Інтеграції з QuickBooks, Xero, NetSuite', 'Corporate cards and expense management
AI expense review (Plus)
Bill pay and accounting
QuickBooks, Xero and NetSuite integrations', 'Фінансові команди компаній у США.', 'Finance teams at US companies.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
