SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'talktoash.com' OR LOWER(`name`) = LOWER('Ash (Slingshot AI)'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ash (Slingshot AI)', NULL, 'https://www.talktoash.com', NULL, NULL, 'AI-співрозмовник, створений спеціально для ментального здоров''я: підтримка 24/7 текстом чи голосом, пам''ять про вашу історію та щотижневі інсайти.', 'An AI built specifically for mental health: 24/7 support by text or voice, memory of your story and weekly insights.', 'Ash від Slingshot AI — AI, створений саме для підтримки ментального здоров''я, а не загальний чат-бот: його навчено на спеціалізованих психологічних даних. Він допомагає розібратися зі стресом, тривогою, стосунками та особистими труднощами, пов''язує думки, почуття й поведінку, запам''ятовує вашу історію та вподобання й щотижня надає персональні інсайти. Спілкуватися можна текстом або голосом цілодобово. Доступний на iOS і у вебі. Важливо: Ash не призначений для кризових ситуацій і не замінює професійне лікування — у кризі варто звертатися на гарячу лінію чи до фахівця. Ціни на сайті не опубліковано.', 'Ash from Slingshot AI is an AI built specifically for mental health support rather than a general chatbot: it is trained on specialised psychological data. It helps with stress, anxiety, relationships and personal challenges, connects thoughts, feelings and behaviours, remembers your story and preferences and gives personalised weekly insights. You can talk to it by text or voice around the clock. It is available on iOS and the web. Important: Ash is not designed for crises and does not replace professional treatment — in a crisis, contact a helpline or a professional. Pricing is not published on the website.', 'AI, навчений на психологічних даних
Текст або голос 24/7
Пам''ять про вашу історію
Щотижневі персональні інсайти', 'AI trained on psychological data
Text or voice 24/7
Remembers your story
Weekly personal insights', 'Дорослі, які шукають підтримку зі стресом, тривогою чи стосунками.', 'Adults seeking support with stress, anxiety or relationships.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
