SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mindsera.com' OR LOWER(`name`) = LOWER('Mindsera'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Mindsera', NULL, 'https://www.mindsera.com', NULL, NULL, 'AI-щоденник для ясності мислення: аналізує емоції, виявляє повторювані теми, пропонує 50+ ментальних моделей і оцінює особистість за моделлю Великої п''ятірки.', 'An AI journal for clear thinking: it analyses emotions, detects recurring topics, offers 50+ mental model templates and assesses personality using the Big Five.', 'Mindsera — «спортзал для розуму», що поєднує ведення щоденника з ментальними моделями. Записи можна писати, надиктовувати або сканувати з паперового щоденника; AI-компаньйон ставить запитання для глибшої рефлексії, аналізує емоції, знаходить повторювані теми й оцінює особистість за моделлю Великої п''ятірки. Є понад 50 шаблонів мислення (мислення з перших принципів, ікігай тощо), щотижневі підсумки й відстеження звичок. Дані шифруються й не використовуються для навчання моделей. Тарифи: Curious — безкоштовно; Genius — $14,99 на місяць або $129 на рік. Доступний у вебі, на iPhone та Android.', 'Mindsera is a ''gym for the mind'' that combines journaling with mental models. You can write, dictate or scan entries from a paper journal; the AI companion asks questions for deeper reflection, analyses emotions, finds recurring topics and assesses personality using the Big Five model. There are 50+ thinking templates (first-principles thinking, ikigai and more), weekly reviews and habit tracking. Data is encrypted and not used for model training. Plans: Curious — free; Genius — $14.99 a month or $129 a year. It is available on the web, iPhone and Android.', 'Щоденник текстом, голосом чи скануванням
Аналіз емоцій і повторюваних тем
50+ ментальних моделей
Оцінка особистості (Велика п''ятірка)', 'Journal by text, voice or scan
Emotion and recurring-topic analysis
50+ mental models
Big Five personality insights', 'Люди, які ведуть щоденник і працюють над самопізнанням.', 'People who journal and work on self-reflection.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
