INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Lyssn', NULL, 'https://www.lyssn.io', NULL, NULL, 'AI для якості й навчання в психологічній допомозі: аналізує записи сесій на відповідність доказовим методам і дає фахівцям зворотний зв''язок для розвитку навичок.', 'AI for quality and training in behavioural health: it analyses session recordings for fidelity to evidence-based practices and gives clinicians feedback to build their skills.', 'Lyssn використовує обробку природної мови, щоб оцінювати терапевтичні сесії та навчання фахівців. Платформа транскрибує сесії, оцінює їхню відповідність доказовим методам терапії та надає модулі розвитку навичок зі зворотним зв''язком у реальному часі, а керівники отримують звіти про якість роботи команди. Розробку засновано на 17 роках академічних досліджень, понад 4,5 млн проаналізованих сесій і понад 65 рецензованих публікаціях. Lyssn використовують понад 100 організацій — державні агенції, системи психологічної допомоги, кризові служби. Ціни — за запитом.', 'Lyssn uses natural language processing to evaluate therapy sessions and clinician training. The platform transcribes sessions, assesses their fidelity to evidence-based therapies and provides skill-building modules with real-time feedback, while managers get reports on team quality. It is grounded in 17 years of academic research, more than 4.5 million analysed sessions and 65+ peer-reviewed publications. More than 100 organisations use Lyssn — government agencies, behavioural health systems and crisis services. Pricing is on request.', 'Оцінка відповідності доказовим методам
Транскрипція сесій
Тренування навичок зі зворотним зв''язком
Звіти про якість роботи команди', 'Fidelity to evidence-based practices
Session transcription
Skill training with feedback
Team quality reports', 'Організації психологічної допомоги, супервізори й навчальні програми.', 'Behavioural health organisations, supervisors and training programmes.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lyssn.io' OR LOWER(`name`) = LOWER('Lyssn')) ORDER BY `id` LIMIT 1);
