INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Lyssn uses natural language processing to evaluate therapy sessions and clinician training. The platform transcribes sessions, assesses their fidelity to evidence-based therapies and provides skill-building modules with real-time feedback, while managers get reports on team quality. It is grounded in 17 years of academic research, more than 4.5 million analysed sessions and 65+ peer-reviewed publications. More than 100 organisations use Lyssn — government agencies, behavioural health systems and crisis services. Pricing is on request.', 'manual' FROM DUAL WHERE @new = 1;
