-- Limbic — Інструменти для психологів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'limbic.ai' OR LOWER(`name`) = LOWER('Limbic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Limbic', NULL, 'https://www.limbic.ai', NULL, NULL, 'Клінічний AI для служб психологічної допомоги: агенти для первинного прийому, тріажу й терапії; єдиний чат-бот у сфері ментального здоров''я з класом IIa у Великій Британії.', 'Clinical AI for mental health services: intake, triage and therapy agents; the only mental health chatbot with UK Class IIa medical device certification.', 'Limbic допомагає службам психологічної допомоги приймати більше пацієнтів. Limbic Access проводить первинний прийом і оцінювання, Limbic Care — клінічний AI-компаньйон між сесіями, а агенти вбудовуються в маршрути направлення та клінічні процеси. Limbic має сертифікацію медичного виробу класу IIa у Великій Британії й використовується в службах NHS Talking Therapies, страхових планах і системах охорони здоров''я. Клієнти повідомляють про вдвічі вищі показники одужання, на 23% менше відсівання та коротші черги. Ціни — після демонстрації.', 'Limbic helps mental health services see more patients. Limbic Access handles intake and assessments, Limbic Care is a clinical AI companion between sessions, and agents embed into referral pathways and clinical workflows. Limbic holds UK Class IIa medical device certification and is used by NHS Talking Therapies services, health plans and health systems. Customers report twice the recovery rates, 23% lower dropout and shorter waits. Pricing is provided after a demo.', 'Первинний прийом і оцінювання (Limbic Access)
Клінічний AI-компаньйон (Limbic Care)
Медичний виріб класу IIa (Велика Британія)
Використовується в NHS Talking Therapies', 'Intake and assessment (Limbic Access)
Clinical AI companion (Limbic Care)
UK Class IIa medical device
Used in NHS Talking Therapies', 'Служби психологічної допомоги, клініки та страхові плани.', 'Mental health services, clinics and health plans.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
